#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_slice_negative_to_capped_to_len(void) {
    // Setup: create a buffer with known data
    // buf->data = "abcdef", length = 6
    buffer_t *buf = buffer_new_with_size(6);
    TEST_ASSERT_NOT_NULL(buf);
    memcpy(buf->data, "abcdef", 6);
    buf->data[6] = '\0';

    // from = 2, to = -1
    // len = 6, ~to = ~(-1) = 0, so to = 6 - 0 = 6
    // to > len is false, so to remains 6
    // n = to - from = 6 - 2 = 4
    // Should copy buf->data[2..5] = "cdef"
    size_t from = 2;
    ssize_t to = -1;

    buffer_t *slice = buffer_slice(buf, from, to);

    // Assertions
    TEST_ASSERT_NOT_NULL(slice);
    helper_assert_buffer_length(slice, 4);
    helper_assert_buffer_data_equals(slice, "cdef", 4);

    // Cleanup
    buffer_free(slice);
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_slice_negative_to_capped_to_len);
    return UNITY_END();
}


